mapper.update:
UPDATE oa_org.identity_directory_source SET acked_sequence = #{sequence}, acked_fingerprint = #{fingerprint}
WHERE tenant_id = #{tenant} AND acked_sequence < #{sequence} AND last_sequence >= #{sequence}
    AND EXISTS (SELECT 1 FROM oa_org.identity_directory_outbox o WHERE o.tenant_id = #{tenant}
        AND o.partition_sequence = #{sequence} AND o.fingerprint = #{fingerprint})
